function toggleMenu(){document.querySelector(".nav-links").classList.toggle("active")}async function handlePaste(){try{const t=await navigator.clipboard.readText(),i=document.getElementById("urlInput");i.value=t;i.focus()}catch(e){console.error("Failed to read clipboard contents: ",e);alert("Could not paste from clipboard. Please paste manually.")}}async function handleDownload(e){e.preventDefault();const u=document.getElementById("urlInput").value,l=document.getElementById("loading"),r=document.getElementById("result"),er=document.getElementById("error");if(!u)return;try{const p=new URL(u);if(!["http:","https:"].includes(p.protocol)){er.innerText="Please enter a valid HTTP or HTTPS URL.";er.style.display="block";return}}catch(x){er.innerText="Please enter a valid URL (e.g., https://www.youtube.com/watch?v=...)";er.style.display="block";return}l.style.display="block";r.style.display="none";er.style.display="none";try{const f=new FormData;f.append("url",u);const s=await fetch("/preview",{method:"POST",body:f}),t=await s.text();let d;try{d=JSON.parse(t)}catch(_){throw new Error("Server error. Please try again later.")}if(!s.ok)throw new Error(d.detail||"Failed to fetch video");document.getElementById("thumb").src=d.thumbnail;document.getElementById("videoTitle").innerText=d.title;document.getElementById("uploader").innerText=d.uploader||"Unknown";document.getElementById("views").innerText=d.view_count||"N/A";document.getElementById("duration").innerText=d.duration||"N/A";r.style.display="block"}catch(err){er.innerText=err.message;er.style.display="block"}finally{l.style.display="none"}}async function triggerDownload(fmt){const s=document.getElementById("loading");s.innerText="Starting download...";s.style.display="block";const u=document.getElementById("urlInput").value;if(!u){s.style.display="none";return}try{if(typeof window.gtag==="function"){window.gtag("event","video_download",{event_category:"Engagement",event_label:fmt,url_downloaded:u})}const f=document.createElement("form");f.method="POST";f.action="/download";const i1=document.createElement("input");i1.type="hidden";i1.name="url";i1.value=u;f.appendChild(i1);const i2=document.createElement("input");i2.type="hidden";i2.name="format";i2.value=fmt;f.appendChild(i2);document.body.appendChild(f);f.submit();document.body.removeChild(f);setTimeout(()=>{s.style.display="none";s.innerText="Processing..."},3e3)}catch(err){alert("Error: "+err.message);s.style.display="none"}}
